    "explanation": "정답 근거\n장수왕은 중국 남북조와 교류했고 광개토 태왕릉비를 건립했으며 427년 평양으로 천도했다.\n\n보기 비교\n영락·신라 지원·왜 격퇴는 광개토 태왕, 살수는 수 전쟁이다. 전연·태학은 고구려 중기 왕들의 단서이고 금관가야 병합은 법흥왕, 642년 정변은 연개소문, 대가야 병합은 진흥왕이다.\n\n기억 연결\n장수왕은 남북조 교류·평양·한성·릉비라는 남진과 외교의 묶음으로 기억한다.",
