    "explanation": "정답 근거\n부경은 고구려의 곡식 창고를 가리킨다. 요약표에서는 정복 활동과 옥저의 공납 등 경제 단서와 함께 정리한다.\n\n보기 비교\n고구려의 정치 회의는 제가 회의와 연결한다. 천군의 제사와 신성 구역은 삼한의 소도이며, 지방관 감찰은 창고인 부경의 기능이 아니다.\n\n기억 연결\n부경이라는 이름을 외울 때 곡식 보관이라는 기능도 함께 붙인다.",
