    "explanation": "정답 근거: 성왕은 538년 사비로 천도하고 국호를 남부여로 정했다. 중앙·지방 조직을 정비하고 한강 회복을 시도했으며 관산성 전투에서 전사했다.\n\n보기 비교: 웅진 천도는 문주왕, 익산 미륵사는 무왕, 대야성 공격은 의자왕 때의 일이다.\n\n기억 연결: 백제의 첫 수도 이동은 한성→웅진이고, 두 번째 수도 이동은 웅진→사비다.",
    "source": "학습 노트 §6 백제 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
