    "answer": "실천과 수행을 강조하는 사상 흐름으로 지방 호족의 성장과 연결된다",
    "explanation": "정답 근거: 선종은 실천·수행을 강조하는 흐름으로 정리되며 신라 말 지방 호족의 성장과 연결된다.\n\n보기 비교: 지방의 중요성을 뒷받침하는 지리 사상은 풍수지리설, 경전·교리를 중시하는 흐름은 선종과 구별되는 교종, 유학 교육 기관은 국학이다.\n\n기억 연결: 선종은 수행, 풍수지리설은 지방의 중요성, 국학은 교육 기관이라는 서로 다른 단서다.",
    "source": "추가노트 §4 신라 말의 변화 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
