    "explanation": "정답 근거: 궁예의 국호는 904년 마진, 911년 태봉으로 바뀌었고, 905년 송악에서 철원으로 천도했다. 국호 변경과 천도는 서로 다른 사건이다.\n\n보기 비교: 고려 건국은 왕건의 918년, 후백제 건국과 완산주는 견훤의 900년, 태봉 전환은 911년이다.\n\n기억 연결: 904 마진-905 철원-911 태봉의 연도 순서를 고정한다.",
