    "answer": "견훤이 신검의 정변으로 쫓겨난 뒤 고려에 귀순했고, 같은 해 신라 경순왕도 고려에 항복했다",
    "explanation": "정답 근거: 견훤은 아들 신검의 정변으로 후백제에서 쫓겨난 뒤 고려에 귀순했다. 같은 935년에 신라 경순왕도 고려에 항복했다.\n\n보기 비교: 후백제를 세운 사람은 견훤이며, 신검은 정변을 일으킨 아들이다. 경순왕은 신라의 마지막 왕으로 발해에 간 것이 아니다.\n\n기억 연결: 견훤의 귀순과 신라 항복을 936년 통일보다 앞에 둔다.",
