    "question": "통일 신라의 토지 제도와 이를 시행한 왕을 바르게 연결한 것은?",
    "answer": "관료전—신문왕 / 정전—성덕왕 / 녹읍 부활—경덕왕",
    "explanation": "정답 근거: 신문왕은 관리에게 관료전을 주고 귀족의 녹읍을 폐지했으며, 성덕왕은 백성에게 정전을 지급했고, 경덕왕 때 귀족의 반발로 녹읍이 부활했다.\n\n보기 비교: 녹읍을 폐지한 왕과 부활시킨 왕을 맞바꾼 연결은 왕권 강화와 귀족 반발의 방향이 거꾸로 된다. 정전을 경덕왕에게 붙인 연결은 백성에게 땅을 준 왕과 귀족에게 녹읍을 돌려준 왕을 섞은 것이고, 관료전을 성덕왕이나 경덕왕에게 붙인 연결도 관료전이 중대 왕권 강화의 출발점이라는 사실과 어긋난다.\n\n기억 연결: 받는 사람으로 구분한다. 관리에게 준 것이 관료전(신문왕), 백성에게 준 것이 정전(성덕왕), 귀족에게 되돌려 준 것이 녹읍(경덕왕)이다. 중대 꼬리 “신문 → 성덕 → 경덕”에 그대로 얹으면 순서까지 함께 남는다.",
    "source": "06강 통일 신라 중대·하대 왕과 사건 · 자체 제작 문제(공식 기출 아님)."
