    "explanation": "정답 근거: 김흠돌의 난은 중대 신문왕이 즉위한 직후 왕의 장인인 진골 귀족이 일으켰고, 김헌창의 난은 하대 헌덕왕 때 웅천주 도독이라는 진골 출신 지방관이 일으켰으며, 원종과 애노의 난은 하대 진성여왕 때 사벌주의 농민이 일으켰다.\n\n보기 비교: 김흠돌의 난을 하대로 옮긴 연결은 중대 왕권 강화의 계기였던 사건의 시기부터 틀린다. 김헌창을 농민으로 본 연결은 진골 출신 지방관의 왕위 계승 불만이라는 성격을 지운다. 원종과 애노를 진골 지방관으로 본 연결은 신라 말 농민 봉기의 주체를 바꾼 것이다.\n\n기억 연결: 주체가 내려가는 계단으로 외운다. 중앙의 진골 귀족(김흠돌·중대 신문왕) → 지방의 진골 관리(김헌창·하대 헌덕왕) → 세금에 짓눌린 농민(원종·애노·하대 진성여왕). 난의 주체가 중앙에서 지방으로, 귀족에서 농민으로 내려갈수록 신라가 무너져 간다.",
    "source": "06강 통일 신라 중대·하대 왕과 사건 · 자체 제작 문제(공식 기출 아님)."
