    "answer": "익산 미륵사지 석탑 · 부여 정림사지 5층 석탑",
    "explanation": "정답 근거: 백제의 대표 탑은 익산 미륵사지 석탑과 부여 정림사지 5층 석탑이다. 앞의 것은 무왕 때 세운 현존 最古 석탑이고, 뒤의 것은 당이 승전 기록을 새겨 ‘평제탑’이라고도 불렸다.\n\n보기 비교: 경주 분황사 모전 석탑과 경주 황룡사 9층 목탑은 둘 다 통일 전 신라 선덕 여왕 때의 탑이다. 경주 감은사지 3층 석탑은 통일 신라 신문왕 때의 쌍탑이고, 화순 쌍봉사 철감선사탑은 통일 신라 하대의 승탑이므로 백제와 묶이지 않는다.\n\n기억 연결: 지명이 곧 나라 앵커다. 익산·부여는 백제, 경주는 신라와 통일 신라, 화순 쌍봉사는 통일 신라 하대 선종이다.",
