    "explanation": "정답 근거: 금동 미륵보살 반가 사유상은 삼국 시대의 불상이고, 국보 83호는 일본 고류사의 목조 미륵보살 반가 사유상과 모습이 매우 비슷하다. 만든 나라는 신라로 보는 견해가 유력하지만 확정되지 않았으므로 나라를 단정하지 않는다.\n\n보기 비교: 두 부처가 나란히 앉은 불상은 발해의 이불병좌상이다. 석굴암 본존불은 통일 신라 경덕왕 때의 불상이다. ‘백제의 미소’는 서산 용현리 마애 여래 삼존상을 가리킨다. 세 보기 모두 다른 불상의 설명을 옮겨 붙인 것이다.\n\n기억 연결: 반가 사유상은 “삼국 시대 + 일본 고류사 목조상과 닮음”까지만 붙이고 나라는 비워 둔다. 나라가 확실한 짝은 고구려—연가 7년명, 백제—서산 용현리, 발해—이불병좌상, 통일 신라—석굴암 본존불이다.",
