    "subject": "한국사",
    "question": "고려 정종 때의 사실로 옳은 것은?",
    "answer": "왕규의 난을 진압하고 거란에 대비하여 광군을 만들었다",
    "explanation": "정답 근거: 정종은 왕규의 난을 진압했고, 거란의 침입에 대비하려고 광군을 창설했다.\n\n보기 비교: 노비안검법은 광종, 최승로의 시무 28조 채택은 성종, 시정 전시과는 경종의 일이다.\n\n기억 연결: 왕 앵커로 군대를 붙인다. 거란 대비용 광군은 정종의 것이고, 나라의 기본 군사 조직인 중앙군 2군 6위는 그 뒤에 갖춰진다. 정종에게는 왕규의 난과 광군 두 가지만 붙여 둔다.",
