    "question": "고려 중서문하성에 대한 설명으로 옳은 것은?",
    "answer": "재신은 정책을 심의·결정하고 낭사는 잘못을 비판하는 일을 맡았다",
    "explanation": "정답 근거: 중서문하성은 국정을 총괄하는 최고 관서로, 2품 이상의 재신이 정책을 심의·결정하고 3품 이하의 낭사가 잘못을 비판했다.\n\n보기 비교: 왕명 출납은 중추원의 승선, 군사 기밀은 중추원의 추밀이 맡았다. 중서문하성의 장관이 문하시중인 것은 맞지만 6부를 거느리고 정책을 집행한 곳은 상서성이다. 화폐와 곡식의 출납·회계는 삼사의 일이다.\n\n기억 연결: 왕 앵커는 2성 6부를 갖춘 성종이다. 중서문하성은 위의 재신이 정하고 아래의 낭사가 따진다로, 상서성은 6부를 데리고 집행한다로 나눈다.",
