    "explanation": "정답 근거: 고려의 중앙군은 2군 6위로, 응양군·용호군인 2군은 국왕의 친위 부대이고 6위는 수도 경비와 국경 방어를 맡았다.\n\n보기 비교: 주현군은 5도에 두어 평상시 농사를 짓는 예비군이고 주진군은 양계의 국경을 지키는 상비군이므로, 둘을 맞바꾼 설명과 주진군을 예비군이라 한 설명은 모두 틀리다. 중앙군은 직업 군인이어서 군인전을 받고 직역을 자손에게 물려주었다.\n\n기억 연결: 왕 앵커로 군대를 잇는다. 정종의 광군에서 시작해 중앙군 2군 6위로 자리 잡는다. 지방군은 지역으로 나눈다. 5도의 주현군은 농사짓다 나오는 예비군, 양계의 주진군은 국경을 지키는 상비군이다.",
