    "explanation": "정답 근거: 신라의 금관과 금귀고리는 금과 은을 정교하게 다룬 세공 기술을 보여 주는 대표 유물이다.\n\n보기 비교: 칠지도와 금동 대향로는 백제의 금속 유물이다. 천문도와 안학궁은 고구려의 것으로, 천문도는 조선 태조 때 천상열차분야지도로 이어졌고 안학궁은 장수왕이 평양으로 옮긴 뒤의 궁궐이다. 온돌이 나온 상경성은 발해의 도읍이다.\n\n기억 연결: 나라 앵커로 갈라 둔다. 신라는 금관과 금귀고리, 백제는 칠지도와 금동 대향로, 고구려는 천문도와 안학궁, 발해는 상경성과 온돌이다.",
